begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('bbbbbbbb-0000-4000-8000-000000000001','timer-ui-a@example.test'),('bbbbbbbb-0000-4000-8000-000000000002','timer-ui-b@example.test');
select ok(not has_function_privilege('anon','public.get_work_timer_context(uuid)','execute'),'anonymous context denied');
select ok(not has_function_privilege('anon','public.set_work_timer_mode(uuid,text,bigint)','execute'),'anonymous mode writes denied');
select ok(not has_table_privilege('authenticated','public.work_timer_preferences','INSERT'),'direct preference writes denied');
select ok(not has_table_privilege('authenticated','public.work_timer_preferences','UPDATE'),'direct preference updates denied');
set local role authenticated;
set local request.jwt.claim.sub='bbbbbbbb-0000-4000-8000-000000000001';
select set_config('test.uip',public.create_project(gen_random_uuid(),'타이머 UI',null)->>'id',true);
select set_config('test.uiw',public.get_project_detail(current_setting('test.uip')::uuid)->'parts'->0->>'workItemId',true);
select set_config('test.uipart',public.apply_project_part_command(current_setting('test.uip')::uuid,gen_random_uuid(),0,'{"type":"create","name":"소매"}')::text,true);
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->>'mode','manual','manual by default');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->'state','null'::jsonb,'no fabricated timer');
select is(public.set_work_timer_mode(current_setting('test.uiw')::uuid,'auto',0)->>'status','applied','auto mode saved');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->>'mode','auto','mode restored from server');
select is(public.get_work_timer_context((current_setting('test.uipart')::jsonb->>'workItemId')::uuid)->>'mode','manual','modes isolated by work item');
select is(public.apply_counter_command('bbbbbbbb-2000-4000-8000-000000000001',current_setting('test.uiw')::uuid,0,'2026-10-20T03:00:00Z','ui-test','{"type":"change","counter":"stitch","delta":1}')->>'status','applied','counter commit independently succeeds');
select is(public.get_work_session()->'state','null'::jsonb,'counter RPC does not pretend timer was atomically started');
select is(public.apply_work_session_command('bbbbbbbb-2000-4000-8000-000000000001','bbbbbbbb-2000-4000-8000-000000000001',current_setting('test.uiw')::uuid,0,'2026-10-20T03:00:00Z','ui-test','start')->>'status','applied','confirmed count may separately request timer start with stable ID');
select is(public.get_work_timer_context((current_setting('test.uipart')::jsonb->>'workItemId')::uuid)->'active'->>'workItemId',current_setting('test.uiw'),'another part receives correct active work identity');
select is(public.get_work_timer_context((current_setting('test.uipart')::jsonb->>'workItemId')::uuid)->>'activeName','타이머 UI · 기본 파트','active work uses real project/part name');
select is(public.set_work_timer_mode(current_setting('test.uiw')::uuid,'manual',1)->>'status','applied','switch to manual does not implicitly end timer');
select is(public.get_work_session()->'state'->>'status','running','mode change leaves active session running');
select is(public.set_work_timer_mode(current_setting('test.uiw')::uuid,'auto',0)->>'status','conflict','mode stale revision conflicts');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->>'mode','manual','conflict does not overwrite mode');
select is(public.apply_work_session_command(gen_random_uuid(),'bbbbbbbb-2000-4000-8000-000000000001',current_setting('test.uiw')::uuid,1,'2026-10-20T03:01:00Z','ui-test','end')->>'status','applied','session safely ended');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->'state'->>'status','ended','ended session restored in workspace');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->'active','null'::jsonb,'no active session after end');
select is(public.apply_work_session_command('bbbbbbbb-2000-4000-8000-000000000002','bbbbbbbb-2000-4000-8000-000000000002',current_setting('test.uiw')::uuid,0,'2026-10-20T03:02:00Z','ui-test','start')->>'status','applied','new session after end');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->'state'->>'sessionId','bbbbbbbb-2000-4000-8000-000000000002','workspace prioritizes current active session over ended history');
select is(public.apply_work_session_command(gen_random_uuid(),'bbbbbbbb-2000-4000-8000-000000000002',current_setting('test.uiw')::uuid,1,'2026-10-20T03:03:00Z','ui-test','end')->>'status','applied','second session ends independently');
select is(public.delete_project(current_setting('test.uip')::uuid,1)->>'result','deleted','project deleted after end');
select is((select count(*) from public.work_timer_preferences),0::bigint,'deleted project preferences hidden by RLS');
select throws_ok(format('select public.get_work_timer_context(%L)',current_setting('test.uiw')),'P0002',null,'deleted work context blocked');
select throws_ok(format('select public.set_work_timer_mode(%L,''auto'',2)',current_setting('test.uiw')),'P0002',null,'deleted work preference edits blocked');
select is(public.restore_project(current_setting('test.uip')::uuid,gen_random_uuid(),2)->>'status','restored','restore project');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->>'mode','manual','preferences preserved after deletion/recovery');
select is(public.update_project(current_setting('test.uip')::uuid,3,'타이머 UI',null,'paused')->>'result','updated','paused project');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->>'canStart','false','paused context read-only for starting/resuming');
select is(public.set_work_timer_mode(current_setting('test.uiw')::uuid,'auto',2)->>'status','applied','mode metadata independent from existing session/counter rules');
select is(public.get_work_timer_context(current_setting('test.uiw')::uuid)->>'activationRevision','1','enabling auto does not replay older counter history');
select is((select revision from public.work_items where id=current_setting('test.uiw')::uuid),1::bigint,'preferences leave counter revision intact');
set local request.jwt.claim.sub='bbbbbbbb-0000-4000-8000-000000000002';
select is((select count(*) from public.work_timer_preferences),0::bigint,'other account preferences hidden');
select throws_ok(format('select public.get_work_timer_context(%L)',current_setting('test.uiw')),'P0002',null,'other account context denied');
select throws_ok(format('select public.set_work_timer_mode(%L,''manual'',3)',current_setting('test.uiw')),'P0002',null,'other account setting denied');
select * from finish();
rollback;
